mkdir -p /app/output && cat > /app/output/styles.css <<'EOF'
:root {
  --navy: #0A1628;
  --navy-2: #11233f;
  --white: #ffffff;
  --gray-50: #f6f8fb;
  --gray-100: #edf1f6;
  --gray-200: #dbe3ec;
  --gray-600: #536179;
  --gray-800: #27344a;
  --accent: #0a9d9a;
  --accent-2: #b08a3a;
  --max: 1200px;
  --radius: 12px;
  --shadow: 0 12px 30px rgba(10, 22, 40, 0.12);
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: var(--gray-800);
  background: var(--white);
  line-height: 1.6;
}
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
.container { width: min(var(--max), 92%); margin: 0 auto; }
.section { padding: 72px 0; }
.section-tight { padding: 48px 0; }
.eyebrow { color: var(--accent); font-size: .78rem; text-transform: uppercase; letter-spacing: .09em; font-weight: 700; }
h1,h2,h3,h4 { margin: 0 0 12px; line-height: 1.2; color: var(--navy); font-family: "Merriweather", Georgia, serif; }
p { margin: 0 0 16px; color: var(--gray-600); }
.btn { display:inline-flex; align-items:center; justify-content:center; min-height:44px; padding:11px 18px; border-radius:999px; font-weight:600; border:1px solid transparent; }
.btn-primary { background: var(--accent); color: var(--white); }
.btn-secondary { border-color: var(--gray-200); color: var(--navy); }
.topbar { background: var(--navy); color: #cad5e7; font-size: .9rem; }
.topbar .container { display:flex; justify-content:space-between; gap: 12px; padding: 10px 0; }
header.site-header { position: sticky; top: 0; z-index: 50; background: rgba(10,22,40,0.97); backdrop-filter: blur(8px); }
.nav-wrap { display:flex; align-items:center; justify-content:space-between; padding: 14px 0; color: var(--white); }
.logo { font-size: 1.35rem; font-weight: 800; letter-spacing: .02em; }
.logo span { color: var(--accent); }
.nav { display:flex; align-items:center; gap: 24px; }
.nav > li { list-style:none; position:relative; }
.nav-link { color:#e8eef9; font-weight: 500; padding: 10px 0; display:inline-flex; align-items:center; gap:6px; }
.nav-link:hover, .nav-link:focus { color: #fff; }
.mega-menu {
  position:absolute; left:50%; transform: translateX(-50%);
  top: 100%; width:min(980px, 95vw); background: var(--white);
  color: var(--gray-800); border-radius: 14px; box-shadow: var(--shadow);
  padding: 26px; display:none; grid-template-columns: 2fr 1fr; gap: 28px; margin-top: 12px;
}
.nav-item-services.open .mega-menu,
.nav-item-services:hover .mega-menu { display:grid; }
.mega-column h4 { font-size: 1rem; margin-bottom: 12px; font-family: Inter, sans-serif; color:var(--gray-800); }
.mega-grid { display:grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 10px 18px; }
.mega-link { padding: 8px 0; border-bottom: 1px solid var(--gray-100); font-size:.95rem; }
.mobile-menu-btn { display:none; background:none; border:none; color:#fff; font-size:1.2rem; min-width:44px; min-height:44px; }
.mobile-nav { display:none; background: var(--white); border-top:1px solid var(--gray-100); }
.mobile-nav .container { padding: 12px 0 18px; }
.mobile-link { display:block; padding: 12px 6px; border-bottom:1px solid var(--gray-100); color: var(--navy); font-weight:600; }
.mobile-accordion button { width:100%; background:none; border:none; text-align:left; padding:12px 6px; font-weight:700; color: var(--navy); min-height:44px; }
.mobile-panel { display:none; padding: 0 0 12px 10px; }
.mobile-accordion.open .mobile-panel { display:block; }
.hero {
  position: relative; min-height: 68vh; display:flex; align-items:flex-end;
  background-size: cover; background-position:center;
}
.hero::before { content:""; position:absolute; inset:0; background: linear-gradient(120deg, rgba(10,22,40,.88) 18%, rgba(10,22,40,.45) 58%, rgba(10,22,40,.2)); }
.hero-content { position:relative; color:#fff; padding: 84px 0; max-width: 700px; }
.hero-content h1 { color:#fff; font-size: clamp(2rem,4vw,3.5rem); }
.grid-3 { display:grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 24px; }
.grid-2 { display:grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 24px; }
.card { border:1px solid var(--gray-100); border-radius: var(--radius); padding: 22px; background:#fff; }
.banner { background: var(--gray-50); border:1px solid var(--gray-100); padding: 16px 18px; border-left: 4px solid var(--accent-2); border-radius: 8px; }
.what-we-do { display:grid; grid-template-columns: 280px 1fr; gap: 30px; }
.tabs-vertical { border-right: 1px solid var(--gray-200); padding-right: 14px; }
.tab-btn { width:100%; text-align:left; background:none; border:none; min-height:44px; padding: 14px 10px; color: var(--gray-600); font-weight:700; border-left:3px solid transparent; }
.tab-btn.active { color: var(--navy); border-left-color: var(--accent); background: var(--gray-50); }
.tab-panel { display:none; }
.tab-panel.active { display:block; }
.insight-card .meta { font-size:.8rem; text-transform:uppercase; letter-spacing:.06em; color:var(--accent); font-weight:700; }
.commitment { background: var(--navy); color:#dce7fb; }
.commitment h2, .commitment h3 { color:#fff; }
.footer { background:#07101d; color:#b5c1d7; padding: 40px 0; }
.footer-grid { display:grid; grid-template-columns:2fr 1fr 1fr; gap: 24px; }
.page-hero-small { min-height: 45vh; }
.cap-grid { display:grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap:20px; }
.sidebar-topics { background: var(--gray-50); border:1px solid var(--gray-100); border-radius: var(--radius); padding:18px; }
.carousel { position: relative; overflow:hidden; }
.carousel-track { display:flex; transition: transform .35s ease; }
.slide { min-width:100%; }
.carousel-controls { display:flex; gap:10px; margin-top:14px; }
.carousel-controls button { min-height:44px; min-width:44px; border-radius:999px; border:1px solid var(--gray-200); background:#fff; }
@media (max-width: 980px) {
  .grid-3, .cap-grid { grid-template-columns: 1fr 1fr; }
  .what-we-do { grid-template-columns: 1fr; }
  .tabs-vertical { border-right:none; border-bottom:1px solid var(--gray-200); padding-right:0; padding-bottom:12px; }
}
@media (max-width: 760px) {
  .nav { display:none; }
  .mobile-menu-btn { display:block; }
  .mobile-nav.open { display:block; }
  .grid-3, .grid-2, .cap-grid, .footer-grid { grid-template-columns: 1fr; }
  .hero { min-height: 58vh; }
}
EOF

